namespace JingPreview {
sealed class UserPreferences {
 public string Magick="",Output="";
 public bool Recursive=false; public List<string> Recent=new List<string>();
 public void Save(string file){XmlDocument d=new XmlDocument();XmlElement r=d.CreateElement("preferences");d.AppendChild(r);r.SetAttribute("magick",Magick);r.SetAttribute("output",Output);r.SetAttribute("recursive",Recursive.ToString());foreach(string p in Recent){XmlElement e=d.CreateElement("recent");e.InnerText=p;r.AppendChild(e);}string temporary=file+".tmp-"+Guid.NewGuid().ToString("N");try{d.Save(temporary);if(File.Exists(file))File.Replace(temporary,file,null);else File.Move(temporary,file);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
 public static XmlDocument ReadXml(string file){XmlReaderSettings settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=1024*1024};XmlDocument d=new XmlDocument();d.XmlResolver=null;using(XmlReader r=XmlReader.Create(file,settings))d.Load(r);return d;}
 public static UserPreferences Load(string file){UserPreferences p=new UserPreferences();if(!File.Exists(file))return p;XmlDocument d=ReadXml(file);XmlElement r=d.DocumentElement;if(r==null||r.Name!="preferences")throw new InvalidDataException("偏好设置格式无效。");p.Magick=r.GetAttribute("magick");p.Output=r.GetAttribute("output");p.Recursive=r.GetAttribute("recursive")=="True";foreach(XmlElement e in r.ChildNodes)if(e.Name=="recent" && p.Recent.Count<12 && !p.Recent.Contains(e.InnerText))p.Recent.Add(e.InnerText);return p;}
}
sealed class BatchItem {
 public string Path,State="待处理",Method="",Dimensions="",Error="",Output=""; public long Bytes,ModifiedTicks;
 public BatchItem(string path){Path=System.IO.Path.GetFullPath(path);try{FileInfo info=new FileInfo(Path);Bytes=info.Length;ModifiedTicks=info.LastWriteTimeUtc.Ticks;}catch{}}
}
static class BatchTools {
 public static bool Known(string path){return Array.IndexOf(Core.Formats,System.IO.Path.GetExtension(path).TrimStart('.').ToUpperInvariant())>=0;}
 public static List<string> Scan(string root,bool recursive,Func<bool> cancelled,Action<string> warning){var result=new List<string>();var pending=new Stack<string>();pending.Push(System.IO.Path.GetFullPath(root));while(pending.Count>0){if(cancelled())break;string dir=pending.Pop();try{if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0){warning("跳过链接目录："+dir);continue;}foreach(string file in Directory.GetFiles(dir)){if(cancelled())return result;if(Known(file))result.Add(file);if(result.Count>=10000){warning("达到单次扫描 10000 个文件上限。");return result;}}if(recursive)foreach(string sub in Directory.GetDirectories(dir))pending.Push(sub);}catch(UnauthorizedAccessException e){warning(e.Message);}catch(IOException e){warning(e.Message);}}return result;}
 public static string Destination(string folder,string input,string extension){string stem=System.IO.Path.GetFileNameWithoutExtension(input);if(stem.Length>70)stem=stem.Substring(0,70);return System.IO.Path.Combine(folder,stem+"-preview-"+Guid.NewGuid().ToString("N").Substring(0,10)+extension);}
 public static string CsvCell(string text){text=text??"";if(text.Length>0 && (text[0]=='='||text[0]=='+'||text[0]=='-'||text[0]=='@'||text[0]=='\t'||text[0]=='\r'))text="'"+text;return "\""+text.Replace("\"","\"\"")+"\"";}
 public static string Csv(IEnumerable<BatchItem> items){StringBuilder s=new StringBuilder("文件,字节,状态,尺寸,解码方式,输出,错误\r\n");foreach(BatchItem i in items)s.AppendLine(String.Join(",",new[]{CsvCell(i.Path),i.Bytes.ToString(),CsvCell(i.State),CsvCell(i.Dimensions),CsvCell(i.Method),CsvCell(i.Output),CsvCell(i.Error)}));return s.ToString();}
 public static void SavePreview(Bitmap source,string destination,int edge,bool jpeg,int quality){
  double scale=edge==0?1:Math.Min(1,(double)edge/Math.Max(source.Width,source.Height));int w=Math.Max(1,(int)Math.Round(source.Width*scale)),h=Math.Max(1,(int)Math.Round(source.Height*scale));
  string temp=destination+".partial-"+Guid.NewGuid().ToString("N");
  try {using(Bitmap b=new Bitmap(w,h,jpeg?PixelFormat.Format24bppRgb:PixelFormat.Format32bppArgb)){using(Graphics g=Graphics.FromImage(b)){g.Clear(jpeg?Color.White:Color.Transparent);g.CompositingMode=System.Drawing.Drawing2D.CompositingMode.SourceOver;g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(source,new Rectangle(0,0,w,h));}if(jpeg){ImageCodecInfo codec=null;foreach(ImageCodecInfo c in ImageCodecInfo.GetImageEncoders())if(c.FormatID==ImageFormat.Jpeg.Guid)codec=c;if(codec==null)throw new InvalidOperationException("JPEG 编码器不可用");using(EncoderParameters p=new EncoderParameters(1)){p.Param[0]=new EncoderParameter(System.Drawing.Imaging.Encoder.Quality,(long)quality);b.Save(temp,codec,p);}}else b.Save(temp,ImageFormat.Png);}File.Move(temp,destination);}finally{if(File.Exists(temp))File.Delete(temp);}
 }
}
static class BatchCodec {
 internal static void WaitForWorker(Process child,Func<bool> cancel,int timeoutMs){Stopwatch watch=Stopwatch.StartNew();while(!child.WaitForExit(100)){if(cancel()||watch.ElapsedMilliseconds>timeoutMs){try{child.Kill();child.WaitForExit(5000);}catch(InvalidOperationException){}if(cancel())throw new OperationCanceledException("任务已取消");throw new TimeoutException("单文件解码超过 "+(timeoutMs/1000.0).ToString("0.###")+" 秒，已结束该解码进程。");}}}
 public static int Worker(string request,string response){XmlDocument result=new XmlDocument();XmlElement r=result.CreateElement("result");result.AppendChild(r);try{XmlElement job=UserPreferences.ReadXml(request).DocumentElement;if(job.Name!="job")throw new InvalidDataException("任务格式无效");string input=job.GetAttribute("input"),output=job.GetAttribute("output"),method;using(Bitmap b=Decoder.Load(input,out method)){r.SetAttribute("dimensions",b.Width+" × "+b.Height);r.SetAttribute("method",method);if(output.Length>0)BatchTools.SavePreview(b,output,Int32.Parse(job.GetAttribute("edge")),job.GetAttribute("jpeg")=="True",Int32.Parse(job.GetAttribute("quality")));}r.SetAttribute("ok","True");}catch(Exception e){r.SetAttribute("ok","False");r.SetAttribute("error",e.Message);}result.Save(response);return r.GetAttribute("ok")=="True"?0:1;}
 public static void ProcessItem(BatchItem item,string destination,int edge,bool jpeg,int quality,Func<bool> cancel,int timeoutMs){
  if(cancel())throw new OperationCanceledException("任务已取消");
  string folder=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"jing-job-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string request=System.IO.Path.Combine(folder,"request.xml"),response=System.IO.Path.Combine(folder,"response.xml");
  try{XmlDocument d=new XmlDocument();XmlElement r=d.CreateElement("job");d.AppendChild(r);r.SetAttribute("input",item.Path);r.SetAttribute("output",destination);r.SetAttribute("edge",edge.ToString());r.SetAttribute("jpeg",jpeg.ToString());r.SetAttribute("quality",quality.ToString());d.Save(request);
   ProcessStartInfo p=new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"--decode-job \""+request+"\" \""+response+"\"");p.UseShellExecute=false;p.CreateNoWindow=true;using(Process child=System.Diagnostics.Process.Start(p)){WaitForWorker(child,cancel,timeoutMs);}
   if(!File.Exists(response))throw new InvalidDataException("解码进程异常退出，可能为第三方处理程序故障。");XmlElement answer=UserPreferences.ReadXml(response).DocumentElement;if(answer.GetAttribute("ok")!="True")throw new InvalidDataException(answer.GetAttribute("error"));item.Dimensions=answer.GetAttribute("dimensions");item.Method=answer.GetAttribute("method");item.Output=destination;item.State=destination.Length==0?"可预览":"已转存";item.Error="";
  }finally{foreach(string f in Directory.GetFiles(folder)){try{File.Delete(f);}catch(IOException){}}try{Directory.Delete(folder);}catch(IOException){}if(destination.Length>0){string parent=System.IO.Path.GetDirectoryName(destination);if(Directory.Exists(parent))foreach(string part in Directory.GetFiles(parent,System.IO.Path.GetFileName(destination)+".partial-*")){try{File.Delete(part);}catch(IOException){}}}}
 }
}
