 void RefreshRecent(){recentFiles.Items.Clear();foreach(string p in preferences.Recent)recentFiles.Items.Add(p);if(recentFiles.Items.Count>0)recentFiles.SelectedIndex=0;}
 void RememberFile(string path){preferences.Recent.RemoveAll(delegate(string p){return String.Equals(p,path,StringComparison.OrdinalIgnoreCase);});preferences.Recent.Insert(0,path);while(preferences.Recent.Count>12)preferences.Recent.RemoveAt(preferences.Recent.Count-1);RefreshRecent();SavePreferences();}
 void SavePreferences(){preferences.Magick=magick;if(outputFolder!=null)preferences.Output=outputFolder.Text;if(recursiveScan!=null)preferences.Recursive=recursiveScan.Checked;try{preferences.Save(System.IO.Path.Combine(Core.Data,"preferences.xml"));}catch(Exception e){Append("偏好设置保存失败："+e.Message);}}
 void Locate(string file){try{Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+System.IO.Path.GetFullPath(file)+"\""){UseShellExecute=true});}catch(Exception e){MessageBox.Show(e.Message);}}
 void OpenFolder(string folder){try{Directory.CreateDirectory(folder);Process.Start(new ProcessStartInfo(folder){UseShellExecute=true});}catch(Exception e){MessageBox.Show(e.Message);}}
 void InitBatch(){
  TabPage page=Page("批量工作台");
  FlowLayoutPanel bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=96,AutoScroll=true,Padding=new Padding(0,6,0,0)};
