  FlowLayoutPanel options=new FlowLayoutPanel{Dock=DockStyle.Top,Height=116,AutoScroll=true};options.Controls.Add(new Label{Text="输出目录",AutoSize=true,Padding=new Padding(4,8,0,0)});outputFolder=new TextBox{Width=420,Text=preferences.Output};options.Controls.Add(outputFolder);batchEdit.Add(outputFolder);Button choose=SmallButton("选择目录",delegate{using(FolderBrowserDialog d=new FolderBrowserDialog{Description="选择转存目录（自动生成新文件，不覆盖已有文件）"})if(d.ShowDialog()==DialogResult.OK)outputFolder.Text=d.SelectedPath;});options.Controls.Add(choose);options.SetFlowBreak(choose,true);batchEdit.Add(choose);
  options.Controls.Add(new Label{Text="格式",AutoSize=true,Padding=new Padding(4,8,0,0)});outputKind=new ComboBox{Width=78,DropDownStyle=ComboBoxStyle.DropDownList};outputKind.Items.AddRange(new object[]{"PNG","JPEG"});outputKind.SelectedIndex=0;options.Controls.Add(outputKind);batchEdit.Add(outputKind);
