 void AddBatchFiles(IEnumerable<string> files){if(batchWorker!=null&&batchWorker.IsBusy)return;HashSet<string> seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(BatchItem i in queue)seen.Add(i.Path);int added=0;foreach(string path in files){if(queue.Count>=10000)break;try{if(File.Exists(path)){string full=System.IO.Path.GetFullPath(path);if(seen.Add(full)){queue.Add(new BatchItem(full));added++;}}}catch(Exception e){Append("文件入队失败："+e.Message);}}RenderQueue();UpdateBatchSummary("新增 "+added+" 项；重复路径已跳过");SelectPage("批量工作台");}
 void RenderQueue(){batchGrid.Rows.Clear();batchRows.Clear();foreach(BatchItem item in queue){int n=batchGrid.Rows.Add(System.IO.Path.GetFileName(item.Path),(item.Bytes/1048576.0).ToString("F2"),item.State,item.Dimensions,item.Error.Length>0?item.Error:item.Method,item.Path);DataGridViewRow row=batchGrid.Rows[n];row.Tag=item;batchRows[item]=row;UpdateBatchRow(item);}FilterQueue();QueueChanged();}
 void UpdateBatchRow(BatchItem item){DataGridViewRow row;if(!batchRows.TryGetValue(item,out row))return;row.Cells[2].Value=item.State;row.Cells[3].Value=item.Dimensions;row.Cells[4].Value=item.Error.Length>0?item.Error:item.Method;row.Cells[4].ToolTipText=item.Error.Length>0?item.Error:item.Method;if(batchDetails!=null&&row.Selected)UpdateBatchDetails();row.DefaultCellStyle.ForeColor=item.State=="失败"||item.State=="超时"?Color.Firebrick:item.State=="可预览"||item.State=="已转存"?Color.FromArgb(23,114,77):ink;}
 void UpdateBatchSummary(string prefix){int ok=0,fail=0;foreach(BatchItem i in queue){if(i.State=="可预览"||i.State=="已转存")ok++;if(i.State=="失败"||i.State=="超时")fail++;}batchSummary.Text=prefix+"  |  共 "+queue.Count+" 项 / 成功 "+ok+" / 失败 "+fail;}
 void SetBatchBusy(bool busy){foreach(Control c in batchEdit)c.Enabled=!busy;cancelBatch.Enabled=busy;}
 void ScanFolder(object sender,EventArgs e){if(batchWorker!=null&&batchWorker.IsBusy)return;using(FolderBrowserDialog d=new FolderBrowserDialog{Description="扫描已知图片格式；目录链接会跳过，最多 10000 项"}){if(d.ShowDialog()!=DialogResult.OK)return;string root=d.SelectedPath;bool recurse=recursiveScan.Checked;List<string> warnings=new List<string>();BackgroundWorker worker=new BackgroundWorker{WorkerSupportsCancellation=true};batchWorker=worker;SetBatchBusy(true);batchProgress.Style=ProgressBarStyle.Marquee;batchSummary.Text="正在扫描："+root;
  worker.DoWork+=delegate(object s,DoWorkEventArgs a){a.Result=BatchTools.Scan(root,recurse,delegate{return worker.CancellationPending;},delegate(string warning){warnings.Add(warning);});};worker.RunWorkerCompleted+=delegate(object s,RunWorkerCompletedEventArgs a){SetBatchBusy(false);batchProgress.Style=ProgressBarStyle.Blocks;batchWorker=null;if(a.Error!=null){UpdateBatchSummary("扫描失败："+a.Error.Message);}else{AddBatchFiles((List<string>)a.Result);UpdateBatchSummary((worker.CancellationPending?"扫描已取消；保留已找到项":"扫描完成")+"，跳过/限制 "+warnings.Count+" 项");}foreach(string warning in warnings)Append("扫描："+warning);worker.Dispose();};worker.RunWorkerAsync();}}
 void StartBatch(bool convert,bool failedOnly,bool pendingOnly=false,bool selectedOnly=false){if(batchWorker!=null&&batchWorker.IsBusy)return;if(failedOnly)convert=retryConvert;else retryConvert=convert;List<BatchItem> selected=new List<BatchItem>();foreach(BatchItem item in queue)if((!failedOnly||item.State=="失败"||item.State=="超时"||item.State=="已取消"||item.State=="文件缺失")&&(!pendingOnly||(item.State!="可预览"&&item.State!="已转存"))&&(!selectedOnly||(batchRows.ContainsKey(item)&&batchRows[item].Selected)))selected.Add(item);if(selected.Count==0){UpdateBatchSummary("没有可处理的项目");return;}string folder=outputFolder.Text.Trim();bool jpeg=outputKind.SelectedIndex==1;int edge=(int)edgeLimit.Value,quality=(int)jpegQuality.Value;if(convert){try{if(folder.Length==0){using(FolderBrowserDialog picker=new FolderBrowserDialog{Description="选择本次批量转存目录"}){if(picker.ShowDialog()!=DialogResult.OK)return;folder=picker.SelectedPath;outputFolder.Text=folder;}}folder=System.IO.Path.GetFullPath(folder);Directory.CreateDirectory(folder);}catch(Exception ex){MessageBox.Show(ex.Message);return;}}SavePreferences();
  BackgroundWorker worker=new BackgroundWorker{WorkerSupportsCancellation=true,WorkerReportsProgress=true};batchWorker=worker;SetBatchBusy(true);batchProgress.Style=ProgressBarStyle.Blocks;batchProgress.Maximum=selected.Count;batchProgress.Value=0;
  worker.DoWork+=delegate{int done=0;foreach(BatchItem item in selected){if(worker.CancellationPending)break;item.State="处理中";item.Error="";worker.ReportProgress(done,item);try{string dest=convert?BatchTools.Destination(folder,item.Path,jpeg?".jpg":".png"):"";BatchCodec.ProcessItem(item,dest,edge,jpeg,quality,delegate{return worker.CancellationPending;},30000);}catch(OperationCanceledException){item.State="已取消";item.Error="用户取消";}catch(TimeoutException ex){item.State="超时";item.Error=ex.Message;}catch(Exception ex){item.State="失败";item.Error=ex.Message;}done++;worker.ReportProgress(done,item);}};
  worker.ProgressChanged+=delegate(object s,ProgressChangedEventArgs e){if(batchWorker!=worker)return;UpdateBatchRow((BatchItem)e.UserState);batchProgress.Value=Math.Min(e.ProgressPercentage,batchProgress.Maximum);UpdateBatchSummary("进度 "+e.ProgressPercentage+" / "+selected.Count);};worker.RunWorkerCompleted+=delegate(object s,RunWorkerCompletedEventArgs e){SetBatchBusy(false);batchWorker=null;foreach(BatchItem item in selected)UpdateBatchRow(item);FilterQueue();QueueChanged();UpdateBatchSummary(e.Error!=null?"任务异常："+e.Error.Message:worker.CancellationPending?"已取消，其余项目保留原状态":"处理完成");Append("批量任务："+batchSummary.Text);worker.Dispose();};worker.RunWorkerAsync();
 }
 void InitMaintenance(){TabPage page=Page("设置与备份");FlowLayoutPanel tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=98,AutoScroll=true};tools.Controls.Add(SmallButton("备份当前设置",delegate{Run("手动备份",delegate{string file=System.IO.Path.Combine(Core.Data,"backup-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".xml");Core.Backup(file);return "已备份："+file;});RefreshBackups();}));tools.Controls.Add(SmallButton("刷新备份列表",delegate{RefreshBackups();}));tools.Controls.Add(SmallButton("恢复选中备份",delegate{if(backupGrid.CurrentRow==null)return;string file=(string)backupGrid.CurrentRow.Tag;Run("恢复备份",delegate{Core.Restore(file);return "已恢复："+file;});}));tools.Controls.Add(SmallButton("打开日志与备份",delegate{OpenFolder(Core.Data);}));tools.Controls.Add(SmallButton("打开输出目录",delegate{if(outputFolder.Text.Trim().Length>0)OpenFolder(outputFolder.Text.Trim());else MessageBox.Show("请在批量工作台选择输出目录。");}));tools.Controls.Add(SmallButton("清空最近记录",delegate{preferences.Recent.Clear();RefreshRecent();SavePreferences();}));tools.Controls.Add(SmallButton("系统文件夹选项",delegate{try{Process.Start("control.exe","folders");}catch(Exception e){MessageBox.Show(e.Message);}}));tools.Controls.Add(SmallButton("刷新资源管理器",delegate{Core.Notify();Append("已向资源管理器发送刷新通知；请重新打开文件夹查看。");}));
  Label help=new Label{Dock=DockStyle.Top,Height=95,Padding=new Padding(8,8,8,0),Text="备份管理\r\n手动备份或每次一键修复时自动备份；选择一项即可恢复当时的显示设置。\r\n快捷键：Ctrl+O 打开图片 · Ctrl+S 转存预览 · F5 刷新格式诊断。\r\n自动记住：最近 12 个文件、外部解码器路径、输出目录、子文件夹扫描选项。"};backupGrid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White};backupGrid.Columns.Add("name","备份文件");backupGrid.Columns.Add("time","修改时间");backupGrid.Columns.Add("size","大小（字节）");page.Controls.Add(backupGrid);page.Controls.Add(help);page.Controls.Add(tools);page.Enter+=delegate{RefreshBackups();};RefreshBackups();}
 void RefreshBackups(){backupGrid.Rows.Clear();try{string[] files=Directory.GetFiles(Core.Data,"backup-*.xml");Array.Sort(files,StringComparer.OrdinalIgnoreCase);Array.Reverse(files);foreach(string f in files){FileInfo i=new FileInfo(f);int n=backupGrid.Rows.Add(i.Name,i.LastWriteTime.ToString("yyyy-MM-dd HH:mm:ss"),i.Length);backupGrid.Rows[n].Tag=f;}}catch(Exception e){Append("备份列表读取失败："+e.Message);}}
 public int UiSmokeTest(string report){string root=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(report)),"ui-fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string image=System.IO.Path.Combine(root,"设计预览.png"),bad=System.IO.Path.Combine(root,"损坏示例.ppm");using(Bitmap b=new Bitmap(640,360)){using(Graphics g=Graphics.FromImage(b)){g.Clear(Color.FromArgb(24,40,60));using(Brush brush=new SolidBrush(Color.FromArgb(30,105,229)))g.FillEllipse(brush,60,60,240,240);using(Font font=new Font("Microsoft YaHei UI",25))g.DrawString("景览 1.2",font,Brushes.White,300,145);}b.Save(image,ImageFormat.Png);}File.WriteAllText(bad,"P6\n2 2\n255\n");
  var lines=new List<string>();AddBatchFiles(new[]{image,image,bad});if(queue.Count!=2)throw new Exception("UI queue deduplication failed");lines.Add("PASS UI queue deduplication");if(tabs.SelectedTab.Text!="批量工作台")throw new Exception("Batch page inaccessible");outputFolder.Text=System.IO.Path.Combine(root,"output");edgeLimit.Value=320;StartBatch(true,false);Stopwatch watch=Stopwatch.StartNew();while(batchWorker!=null){Application.DoEvents();System.Threading.Thread.Sleep(10);if(watch.ElapsedMilliseconds>65000)throw new TimeoutException("UI batch task timeout");}if(queue[0].State!="已转存"||queue[1].State!="失败")throw new Exception("Unexpected UI job results: "+queue[0].State+" / "+queue[1].State);using(Bitmap b=new Bitmap(queue[0].Output))if(b.Width!=320)throw new Exception("Output dimensions");lines.Add("PASS UI batch export / progress / failure isolation");SaveFormImage(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(report),"batch-ui.png"));OpenStartup(image);while(UseWaitCursor){Application.DoEvents();System.Threading.Thread.Sleep(10);}if(picture.Image==null)throw new Exception("Preview did not load");Transform(RotateFlipType.Rotate90FlipNone);if(picture.Image.Width!=360||picture.Image.Height!=640)throw new Exception("Rotation did not apply");lines.Add("PASS UI preview and rotate without modifying input");using(Bitmap original=new Bitmap(image))if(original.Width!=640)throw new Exception("Original modified");SaveFormImage(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(report),"preview-ui.png"));File.WriteAllText(System.IO.Path.Combine(root,"batch-results.csv"),BatchTools.Csv(queue),new UTF8Encoding(true));SavePreferences();if(UserPreferences.Load(System.IO.Path.Combine(Core.Data,"preferences.xml")).Recent[0]!=image)throw new Exception("Recent files not persisted");lines.Add("PASS UI preferences and recent file persistence");ConvenienceUiTests(lines,root);LayoutUiTests(lines);SelectPage("批量工作台");SaveFormImage(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(report),"batch-ui.png"));SelectPage("图片预览与转存");SaveFormImage(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(report),"preview-ui.png"));File.WriteAllLines(report,lines.ToArray(),Encoding.UTF8);return 0;
 }
 void SaveFormImage(string path){Application.DoEvents();Refresh();Update();using(Bitmap b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(path,ImageFormat.Png);}}
