static class ProductivityTests {
 public static void Run(Action<string,Action> test,string temp){
  test("Preferences round-trip and DTD rejection",delegate{string p=System.IO.Path.Combine(temp,"preferences.xml");UserPreferences u=new UserPreferences{Magick="C:\\工具\\magick.exe",Output="D:\\图片",Recursive=true};u.Recent.Add("C:\\图 & 片.png");u.Save(p);UserPreferences v=UserPreferences.Load(p);if(v.Magick!=u.Magick||!v.Recursive||v.Recent[0]!=u.Recent[0])throw new Exception("round trip");u.Output="second";u.Save(p);if(UserPreferences.Load(p).Output!="second")throw new Exception("atomic update");File.WriteAllText(p,"<!DOCTYPE x [<!ENTITY a 'x'>]><preferences>&a;</preferences>");bool rejected=false;try{UserPreferences.Load(p);}catch(XmlException){rejected=true;}if(!rejected)throw new Exception("DTD accepted");});
  test("Batch recursive scan, filters and cancellation",delegate{string folder=System.IO.Path.Combine(temp,"scan");Directory.CreateDirectory(folder);string child=System.IO.Path.Combine(folder,"sub");Directory.CreateDirectory(child);File.WriteAllText(System.IO.Path.Combine(folder,"one.PNG"),"");File.WriteAllText(System.IO.Path.Combine(folder,"readme.txt"),"");File.WriteAllText(System.IO.Path.Combine(child,"two.PSD"),"");if(BatchTools.Scan(folder,false,delegate{return false;},delegate{}).Count!=1||BatchTools.Scan(folder,true,delegate{return false;},delegate{}).Count!=2||BatchTools.Scan(folder,true,delegate{return true;},delegate{}).Count!=0)throw new Exception("scan");foreach(string f in Directory.GetFiles(child))File.Delete(f);Directory.Delete(child);foreach(string f in Directory.GetFiles(folder))File.Delete(f);Directory.Delete(folder);});
  test("PNG/JPEG resize, no overwrite and original preserved",delegate{string p=System.IO.Path.Combine(temp,"resize.png"),jpg=System.IO.Path.Combine(temp,"resize.jpg");using(Bitmap b=new Bitmap(40,20)){b.SetPixel(0,0,Color.Red);BatchTools.SavePreview(b,p,10,false,90);BatchTools.SavePreview(b,jpg,10,true,90);if(b.Width!=40)throw new Exception("original changed");bool blocked=false;try{BatchTools.SavePreview(b,p,10,false,90);}catch(IOException){blocked=true;}if(!blocked)throw new Exception("overwrite allowed");}using(Bitmap b=new Bitmap(p))if(b.Width!=10||b.Height!=5)throw new Exception("dimensions");using(Bitmap b=new Bitmap(jpg))if(b.Width!=10||b.Height!=5)throw new Exception("jpeg dimensions");});
  test("CSV quote escaping and formula neutralization",delegate{if(BatchTools.CsvCell("=1+1")!="\"'=1+1\""||BatchTools.CsvCell("a,\"b")!="\"a,\"\"b\"")throw new Exception("CSV");});
  test("Isolated decoder process and export",delegate{string input=System.IO.Path.Combine(temp,"sample.png"),output=BatchTools.Destination(temp,input,".png");BatchItem item=new BatchItem(input);BatchCodec.ProcessItem(item,output,2,false,90,delegate{return false;},30000);if(item.State!="已转存"||!File.Exists(output))throw new Exception("worker");using(Bitmap b=new Bitmap(output))if(b.Width!=2)throw new Exception("resize");});
  test("Isolated decoder reports damaged input",delegate{BatchItem item=new BatchItem(System.IO.Path.Combine(temp,"bad.ppm"));bool rejected=false;try{BatchCodec.ProcessItem(item,"",0,false,90,delegate{return false;},30000);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("damage accepted");});
  test("Cancelled batch job creates no output",delegate{string target=System.IO.Path.Combine(temp,"cancelled.png");bool cancelled=false;try{BatchCodec.ProcessItem(new BatchItem(System.IO.Path.Combine(temp,"sample.png")),target,0,false,90,delegate{return true;},30000);}catch(OperationCanceledException){cancelled=true;}if(!cancelled||File.Exists(target))throw new Exception("cancel ignored");});
 }
}
